        .parity-card.depression .parity-value { color: var(--accent-teal); }
        .parity-card.anxiety .parity-value { color: var(--accent-amber); }

        .parity-card .parity-unit {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        .parity-vs {
            display: flex;
            align-items: center;
            justify-content: center;
            font-family: var(--font-display);
            font-size: clamp(0.8rem, 1.5vw, 1.2rem);
            color: var(--text-muted);
            font-style: italic;
            min-width: clamp(30px, 4vw, 50px);
        }

        .parity-note {
            font-size: var(--body-size);
            color: var(--text-secondary);
            line-height: 1.5;
            max-width: min(85vw, 700px);
            margin-top: clamp(0.5rem, 1.5vh, 1rem);
        }

        .parity-note strong { color: var(--accent-teal); }

        /* ===========================================
           SLIDE 5: SEVERE CONDITIONS
           =========================================== */
        .severity-comparison {
            display: flex;
            gap: clamp(1rem, 3vw, 3rem);
            max-width: min(90vw, 850px);
            width: 100%;
            align-items: flex-end;
        }

        .severity-col {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .severity-bar-wrap {
            width: 100%;
            max-width: 120px;
            position: relative;
        }

        .severity-bar {
            width: 100%;
            border-radius: 6px 6px 0 0;
            position: relative;
            display: flex;
            align-items: flex-end;
            justify-content: center;
        }

        .severity-bar-inner {
            width: 100%;
            border-radius: 6px 6px 0 0;
