            align-items: flex-start;
            justify-content: center;
            padding-top: clamp(4px, 0.8vh, 8px);
        }

        .severity-bar-val {
            font-family: var(--font-body);
            font-size: clamp(0.65rem, 1.1vw, 0.9rem);
            font-weight: 700;
            color: var(--bg-primary);
